begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select is(public.classify_escalation('What is the monthly price?'),null::jsonb,'ordinary price question is not a dispute');
select is(public.classify_escalation('What is your refund policy?'),null::jsonb,'ordinary policy question is not a refund request');
select is(public.classify_escalation('Grammar check: I paid but no access'),null::jsonb,'quotation/grammar exercise is not a customer dispute');
select is(public.classify_escalation('I paid but no access')->>'category','missing_access','paid/no-access detected');
select is(public.classify_escalation('My payment is not reflected')->>'category','payment_dispute','missing payment detected');
select is(public.classify_escalation('I want a refund')->>'severity','HIGH','refund request high');
select is(public.classify_escalation('You are a scam')->>'category','fraud_accusation','fraud allegation detected');
select is(public.classify_escalation('My lawyer will sue you')->>'category','legal_threat','legal threat detected');
select is(public.classify_escalation('I lost my money')->>'category','financial_loss','financial loss detected');
select is(public.classify_escalation('My account was hacked')->>'severity','CRITICAL','security critical');
select is(public.classify_escalation('I am unhappy, VIP complaint')->>'severity','MEDIUM','VIP complaint medium');
select is(public.classify_escalation('Prices contradict each other')->>'category','knowledge_conflict','knowledge conflict detected');
select is(public.classify_escalation('Please talk to a human')->>'category','human_request','human request detected');
select is(public.classify_escalation('Non-urgent review please')->>'severity','LOW','low priority explicit review supported');
select is(public.classify_escalation('İade istiyorum')->>'locale','tr','Turkish detected');
select is(public.classify_escalation('Мой аккаунт взломали')->>'locale','ru','Russian detected');
select is(public.classify_escalation('أريد استرداد أموالي')->>'locale','ar','Arabic detected');
select ok(not has_function_privilege('authenticated','public.configure_phase12_escalation(uuid,boolean,text,text,text)','EXECUTE'),'browser cannot activate or set destination');
select ok(not has_function_privilege('authenticated','public.escalation_complete_notification(uuid,uuid,uuid,jsonb)','EXECUTE'),'browser cannot fabricate notified receipt');
select ok(not has_table_privilege('service_role','private.escalation_controls','INSERT'),'runtime cannot directly edit approval controls');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at) values
 ('c1200000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p12-manager@example.test','not-used',now()),
 ('c1200000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p12-support@example.test','not-used',now());
insert into public.tenants(id,name,slug) values('c1210000-0000-4000-8000-000000000001','Phase12 A','phase12-sandbox-a'),('c1210000-0000-4000-8000-000000000002','Phase12 B','phase12-sandbox-b'),('c1210000-0000-4000-8000-000000000003','Not approved','normal-tenant');
insert into public.tenant_members(tenant_id,user_id,role) values('c1210000-0000-4000-8000-000000000001','c1200000-0000-4000-8000-000000000001','manager'),('c1210000-0000-4000-8000-000000000001','c1200000-0000-4000-8000-000000000002','support');
select throws_ok($$select public.configure_phase12_escalation('c1210000-0000-4000-8000-000000000003',true,'test-approval')$$,'42501','isolated escalation scope required','activation restricted to isolated sandbox');
select throws_ok($$select public.configure_phase12_escalation('c1210000-0000-4000-8000-000000000001',true,'test-approval','-1003944824067','99999')$$,'23514',null,'VIP alert destination denied');
select public.configure_phase12_escalation('c1210000-0000-4000-8000-000000000001',true,'synthetic-test-approval');
select public.ingest_telegram_message('c1210000-0000-4000-8000-000000000001','p12-ordinary','12001','12001','12001',null,'Test',null,'What is your refund policy?',null,now());
select is((select count(*) from public.escalation_cases where tenant_id='c1210000-0000-4000-8000-000000000001'),0::bigint,'ordinary ingestion creates no case');
update public.conversations set runtime_mode='AI_ACTIVE',human_takeover=false,automatic_replies_enabled=true,automatic_replies_enabled_at=now() where tenant_id='c1210000-0000-4000-8000-000000000001';
select public.ingest_telegram_message('c1210000-0000-4000-8000-000000000001','p12-dispute','12002','12001','12001',null,'Test',null,'I paid but no access',null,now());
create temporary table p12_scope as select id,conversation_id,revision,source_message_id from public.escalation_cases where tenant_id='c1210000-0000-4000-8000-000000000001';
select is((select count(*) from p12_scope),1::bigint,'one source-bound case created synchronously');
select ok((select human_takeover and runtime_mode='HUMAN_TAKEOVER' and not automatic_replies_enabled from public.conversations where id=(select conversation_id from p12_scope)),'high risk pauses AI before ingestion commits');
select public.ingest_telegram_message('c1210000-0000-4000-8000-000000000001','p12-dispute','12002','12001','12001',null,'Test',null,'I paid but no access',null,now());
select is((select count(*) from public.escalation_evidence where case_id=(select id from p12_scope)),1::bigint,'duplicate provider update adds no evidence/case');
select public.ingest_telegram_message('c1210000-0000-4000-8000-000000000001','p12-fraud','12003','12001','12001',null,'Test',null,'You are a scam',null,now());
select is((select count(*) from public.escalation_cases where tenant_id='c1210000-0000-4000-8000-000000000001'),1::bigint,'same conversation merges concurrent categories into active case');
select is((select severity from public.escalation_cases where id=(select id from p12_scope)),'CRITICAL','new evidence raises priority');
select is((select status from public.escalation_notifications where case_id=(select id from p12_scope)),'BLOCKED','missing destination visible and never notified');
select is(public.escalation_claim_notification('c1210000-0000-4000-8000-000000000001'),null::jsonb,'missing destination cannot claim/send');
select is(public.escalation_queue_safe_response('c1210000-0000-4000-8000-000000000001',(select id from p12_scope)),null::uuid,'tenant outbound kill switch suppresses safe response');
update public.tenants set outbound_messaging_enabled=true where id='c1210000-0000-4000-8000-000000000001';
create temporary table p12_ack as select public.escalation_queue_safe_response('c1210000-0000-4000-8000-000000000001',(select id from p12_scope)) id;
select ok((select id is not null from p12_ack),'one canonical safe response can queue while AI is paused');
select is((select content from public.messages where id=(select id from p12_ack)),'I cannot verify this here. This needs human review.','safe acknowledgment makes no completed-action claim');
select is(public.escalation_queue_safe_response('c1210000-0000-4000-8000-000000000001',(select id from p12_scope)),null::uuid,'duplicate safe acknowledgment cannot queue');
select ok(public.escalation_claim_safe_response('c1210000-0000-4000-8000-000000000001',(select id from p12_ack)),'safe delivery uses exclusive claim');
select ok(not public.escalation_claim_safe_response('c1210000-0000-4000-8000-000000000001',(select id from p12_ack)),'second sender cannot claim safe acknowledgment');
select public.record_outbound_message_result('c1210000-0000-4000-8000-000000000001',(select id from p12_ack),'failed',null,0,'SYNTHETIC_DELIVERY_UNCERTAIN',null);
update public.tenants set outbound_messaging_enabled=false where id='c1210000-0000-4000-8000-000000000001';
select public.configure_phase12_escalation('c1210000-0000-4000-8000-000000000001',true,'synthetic-test-approval','12345','99999');
create temporary table p12_job as select public.escalation_claim_notification('c1210000-0000-4000-8000-000000000001') value;
select ok((select value is not null from p12_job),'configured approved destination can claim');
select is(public.escalation_claim_notification('c1210000-0000-4000-8000-000000000001'),null::jsonb,'second worker cannot claim same notification');
select throws_ok($$select public.escalation_complete_notification('c1210000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from p12_job),gen_random_uuid(),'{"result":"SENT","provider_status":200,"provider_message_id":"42"}')$$,'42501','notification lease denied','stale worker cannot complete');
select throws_ok($$select public.escalation_complete_notification('c1210000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from p12_job),(select (value->>'lease_token')::uuid from p12_job),'{"result":"SENT","provider_status":200}')$$,'22023','notification receipt invalid','success without provider receipt denied');
select public.escalation_complete_notification('c1210000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from p12_job),(select (value->>'lease_token')::uuid from p12_job),'{"result":"RETRY","provider_status":429,"retry_after":1}');
update public.escalation_notifications set available_at=now() where case_id=(select id from p12_scope);
truncate p12_job;insert into p12_job select public.escalation_claim_notification('c1210000-0000-4000-8000-000000000001');
select public.escalation_complete_notification('c1210000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from p12_job),(select (value->>'lease_token')::uuid from p12_job),'{"result":"SENT","provider_status":200,"provider_message_id":"42"}');
select is((select status from public.escalation_notifications where case_id=(select id from p12_scope)),'SENT','only recorded provider receipt marks notification sent');
select is((select count(*) from public.escalation_notification_attempts where notification_id=(select (value->>'id')::uuid from p12_job)),2::bigint,'retry and success evidence append-only');
select is(public.escalation_claim_notification('c1210000-0000-4000-8000-000000000001'),null::jsonb,'sent notification cannot be replayed');
-- The financial/access boundary remains untouched.
select is((select count(*) from public.domain_events where tenant_id='c1210000-0000-4000-8000-000000000001' and event_type in ('payment.confirmed','access.granted','subscription.started')),0::bigint,'escalation has no financial or access authority');
select is((select count(*) from public.subscriptions where tenant_id='c1210000-0000-4000-8000-000000000001'),0::bigint,'no subscription mutation');
grant select on p12_scope to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','c1200000-0000-4000-8000-000000000002',true);
select lives_ok($$select public.admin_escalation_list('c1210000-0000-4000-8000-000000000001')$$,'support can read case');
select throws_ok($$select public.admin_escalation_action('c1210000-0000-4000-8000-000000000001',(select id from p12_scope),2,'takeover')$$,'42501','escalation control denied','support cannot control case');
select set_config('request.jwt.claim.sub','c1200000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.admin_escalation_list('c1210000-0000-4000-8000-000000000002')$$,'42501','escalation read denied','wrong-tenant read denied');
select throws_ok($$select public.set_conversation_automatic_replies('c1210000-0000-4000-8000-000000000001',(select conversation_id from p12_scope),true,gen_random_uuid())$$,'42501','resolve and return through escalation control','existing enable action cannot bypass case');
select throws_ok($$select public.admin_escalation_action('c1210000-0000-4000-8000-000000000001',(select id from p12_scope),1,'takeover')$$,'40001','case revision conflict','stale case control denied');
select throws_ok($$select public.admin_escalation_action('c1210000-0000-4000-8000-000000000001',(select id from p12_scope),2,'assign','c1200000-0000-4000-8000-000000000002')$$,'42501','active tenant manager required','cannot assign unsupported role');
select public.admin_escalation_action('c1210000-0000-4000-8000-000000000001',(select id from p12_scope),2,'assign','c1200000-0000-4000-8000-000000000001');
select public.admin_escalation_action('c1210000-0000-4000-8000-000000000001',(select id from p12_scope),3,'acknowledge');
select public.admin_escalation_action('c1210000-0000-4000-8000-000000000001',(select id from p12_scope),4,'takeover');
select is((select status from public.escalation_cases where id=(select id from p12_scope)),'IN_PROGRESS','manager takes ownership');
-- A manual reply must retain tenant gating, ownership and provider evidence.
reset role;
update public.tenants set outbound_messaging_enabled=true where id='c1210000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','c1200000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.queue_outbound_message('c1210000-0000-4000-8000-000000000001',(select conversation_id from p12_scope),'Synthetic manual review reply','phase12-manual',gen_random_uuid())$$,'assigned manager can queue manual reply');
select is((select first_response_at from public.escalation_cases where id=(select id from p12_scope)),null::timestamptz,'queued reply is not a delivered response');
reset role;
select public.record_outbound_message_result('c1210000-0000-4000-8000-000000000001',(select id from public.messages where tenant_id='c1210000-0000-4000-8000-000000000001' and idempotency_key='phase12-manual'),'sent','synthetic-provider-receipt',200,null,null);
select ok((select first_response_at is not null from public.escalation_cases where id=(select id from p12_scope)),'first response requires recorded provider success');
set local role authenticated;
select set_config('request.jwt.claim.sub','c1200000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.admin_escalation_action('c1210000-0000-4000-8000-000000000001',(select id from p12_scope),5,'resolve')$$,'22023','resolution note required','resolution evidence mandatory');
select public.admin_escalation_action('c1210000-0000-4000-8000-000000000001',(select id from p12_scope),5,'resolve',null,'Reviewed; no payment or access action performed.');
select throws_ok($$select public.set_conversation_automatic_replies('c1210000-0000-4000-8000-000000000001',(select conversation_id from p12_scope),true,gen_random_uuid())$$,'42501','resolve and return through escalation control','resolution alone cannot bypass return boundary');
select public.admin_escalation_action('c1210000-0000-4000-8000-000000000001',(select id from p12_scope),6,'return');
select ok((select automatic_replies_enabled and runtime_mode='AI_ACTIVE' and not human_takeover and escalation_return_boundary is not null from public.conversations where id=(select conversation_id from p12_scope)),'safe return enables only future sources');
reset role;
select throws_ok($$insert into public.messages(tenant_id,conversation_id,customer_id,messaging_contact_id,provider_connection_id,direction,message_type,content,status,provider_chat_id,reply_to_message_id,idempotency_key,actor_type,actor_id,correlation_id,occurred_at)
 select tenant_id,conversation_id,customer_id,messaging_contact_id,provider_connection_id,'outbound','text','Stale AI draft','pending',provider_chat_id,id,'phase12-stale-draft','SYSTEM','quality-approved-reply',gen_random_uuid(),now() from public.messages where id=(select source_message_id from p12_scope)$$,'42501','escalation blocks automatic reply','return boundary rejects historical AI draft');
select throws_ok($$update public.escalation_history set action='fabricated' where case_id=(select id from p12_scope)$$,'42501','entitlement evidence immutable','case history immutable');
select is((select count(*) from private.agent_tool_registry),7::bigint,'AI tool whitelist unchanged');
-- Exercise deferred QA integration, including legacy Phase 7 names and proposal persistence order.
select public.configure_phase12_escalation('c1210000-0000-4000-8000-000000000002',true,'synthetic-quality-test');
select public.ingest_telegram_message('c1210000-0000-4000-8000-000000000002','p12-quality-confidence','12201','12201','12201',null,'Test',null,'Explain this detail',null,now());
select public.ingest_telegram_message('c1210000-0000-4000-8000-000000000002','p12-quality-conflict','12202','12202','12202',null,'Test',null,'Explain this offer',null,now());
select public.ingest_telegram_message('c1210000-0000-4000-8000-000000000002','p12-quality-loss','12203','12203','12203',null,'Test',null,'Explain this report',null,now());
do $$declare v uuid;task uuid;run uuid;qc uuid;r record;begin
 v:=private.ensure_shadow_agent('c1210000-0000-4000-8000-000000000002');qc:=private.ensure_conversation_quality_config('c1210000-0000-4000-8000-000000000002');
 for r in select m.*,de.id event_id from public.messages m join public.domain_events de on de.tenant_id=m.tenant_id and de.payload->>'message_id'=m.id::text and de.event_type='message.received' where m.tenant_id='c1210000-0000-4000-8000-000000000002' loop
  insert into public.agent_tasks(tenant_id,agent_definition_id,agent_version_id,customer_id,conversation_id,source_event_id,task_type,objective,execution_mode,idempotency_key,correlation_id)
   select r.tenant_id,agent_definition_id,v,r.customer_id,r.conversation_id,r.event_id,'quality-test','Synthetic deferred QA escalation test','SHADOW','p12-qa:'||r.id,gen_random_uuid() from public.agent_versions where id=v returning id into task;
  insert into public.agent_runs(tenant_id,task_id,agent_version_id,attempt_number,execution_mode,worker_id) values(r.tenant_id,task,v,1,'SHADOW','p12-quality-fixture') returning id into run;
  insert into public.conversation_quality_evaluations(tenant_id,run_id,quality_config_id,director_output,style_profile,qa_scores,qa_action,qa_reasons,factual_confidence,escalation_category,customer_facing_blocked,context_manifest_ref,prompt_version,director_version,renderer_version,qa_version,model_provider,model_name)
   values(r.tenant_id,run,qc,'{}','{"language":"ar"}','{}','verify_or_escalate','{}','unknown',case r.provider_message_id when '12202' then 'knowledge_conflict' when '12203' then 'financial_loss_complaint' end,true,run,'fixture','fixture','fixture','fixture','mock','synthetic');
  insert into public.agent_proposals(tenant_id,task_id,run_id,proposal_type,original_payload,confidence) values(r.tenant_id,task,run,'message_draft','{}',0.4);
 end loop;
end;$$;
set constraints phase12_quality immediate;
select is((select count(*) from public.escalation_cases where tenant_id='c1210000-0000-4000-8000-000000000002'),3::bigint,'deferred QA creates three source-linked cases');
select ok(exists(select 1 from public.escalation_cases where tenant_id='c1210000-0000-4000-8000-000000000002' and category='low_confidence' and severity='MEDIUM' and locale='ar'),'low proposal confidence creates medium case with preserved locale');
select ok(exists(select 1 from public.escalation_cases e join public.conversations c on c.id=e.conversation_id where e.tenant_id='c1210000-0000-4000-8000-000000000002' and e.category='knowledge_conflict' and e.severity='HIGH' and c.human_takeover),'QA knowledge conflict synchronously pauses AI');
select ok(exists(select 1 from public.escalation_cases where tenant_id='c1210000-0000-4000-8000-000000000002' and category='financial_loss' and severity='CRITICAL'),'Phase 7 financial-loss classification retains critical severity');
select * from finish();
rollback;
